cells={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
from itertools import combinations
# enumerate connected 2x2 squares and 3-cell Ls; exact covers all cells
shapes=[]
for r in range(4):
 for c in range(6):
  sq={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  if sq<=cells: shapes.append(('S',sq))
  box={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  for missing in box:
   sh=box-{missing}
   if sh<=cells: shapes.append((f'L{missing}',sh))
def rec(rem, chosen):
 if not rem: return [chosen]
 x=min(rem)
 ans=[]
 for typ,sh in shapes:
  if x in sh and sh<=rem:
   ans+=rec(rem-sh,chosen+[(typ,sh)])
 return ans
sol=rec(cells,[])
print('solutions',len(sol))
for ss in sol[:15]: print([(t,sorted(s)) for t,s in ss])
